     "steps": [
      {
       "title": "Write the condition for no x-axis crossing",
       "lines": [
        {
         "text": "The graph does not cross the $x$-axis when there are no real roots: $b^2-4ac<0$."
        }
       ]
      },
      {
       "title": "Substitute a = 1, b = 5, c = p",
       "lines": [
        {
         "tex": "5^2 - 4(1)(p) &< 0"
        },
        {
         "tex": "25 - 4p &< 0"
        },
        {
         "tex": "-4p &< -25"
        },
        {
         "tex": "p &> 6.25"
        }
       ]
      },
      {
       "title": "Pick the integers in the allowed range",
       "lines": [
        {
         "text": "$p$ is an integer with $-3 \\le p \\le 8$, so $p$ must be above $6.25$ and at most $8$."
        },
        {
         "tex": "p &= 7 \\text{ or } p = 8"
        }
       ]
      }
     ],
     "finalAnswer": "p = 7 \\text{ or } p = 8"
