    "workedSolution": {
     "steps": [
      {
       "title": "Set S_n = 820 and rearrange to a quadratic",
       "lines": [
        {
         "tex": "2n^2 + n &= 820"
        },
        {
         "tex": "2n^2 + n - 820 &= 0"
        }
       ]
      },
      {
       "title": "Factorise and solve",
       "lines": [
        {
         "tex": "(2n + 41)(n - 20) &= 0"
        },
        {
         "tex": "n &= -\\frac{41}{2} \\quad \\text{or} \\quad n = 20"
        }
       ]
      },
      {
       "title": "Reject the impossible solution",
       "lines": [
        {
         "text": "The number of patterns must be positive, so $n = -\\frac{41}{2}$ is rejected."
        },
        {
         "tex": "n &= 20"
        }
       ]
      }
     ],
     "finalAnswer": "n = 20\\text{ patterns}"
    }
