     "steps": [
      {
       "title": "Use the distance formula for P(2, m) and B(6, 4)",
       "lines": [
        {
         "tex": "\\sqrt{(6 - 2)^2 + (4 - m)^2} &= \\sqrt{41}"
        },
        {
         "tex": "\\sqrt{16 + (m - 4)^2} &= \\sqrt{41}"
        }
       ]
      },
      {
       "title": "Square both sides and expand",
       "lines": [
        {
         "tex": "16 + (m - 4)^2 &= 41"
        },
        {
         "tex": "16 + m^2 - 8m + 16 &= 41"
        },
        {
         "tex": "m^2 - 8m - 9 &= 0"
        }
       ]
      },
      {
       "title": "Factorise and solve",
       "lines": [
        {
         "tex": "(m + 1)(m - 9) &= 0"
        },
        {
         "tex": "m &= -1 \\text{ or } m = 9"
        },
        {
         "text": "$P$ is below the $x$-axis, so $m$ is negative. Reject $m = 9$."
        }
       ]
      },
      {
       "title": "Plot P",
       "lines": [
        {
         "text": "$P(2, -1)$ is $2$ across and $1$ down."
        }
       ]
      }
     ],
     "finalAnswer": "m = -1,\\ P(2, -1)",
