     "steps": [
      {
       "title": "Find the fall in value in year 1",
       "lines": [
        {
         "tex": "30\\,000 - 24\\,000 &= 6000"
        }
       ]
      },
      {
       "title": "Write the fall as a percentage of the starting value",
       "lines": [
        {
         "tex": "\\text{Percentage fall} &= \\frac{6000}{30\\,000} \\times 100"
        },
        {
         "tex": "&= 20"
        }
       ]
      }
     ],
     "finalAnswer": "20\\%"
