    "workedSolution": {
     "steps": [
      {
       "title": "Make n the subject",
       "lines": [
        {
         "tex": "t &= 2n + 1"
        },
        {
         "tex": "t - 1 &= 2n"
        },
        {
         "tex": "\\frac{t-1}{2} &= n"
        },
        {
         "tex": "n &= \\frac{t-1}{2}"
        }
       ]
      }
     ],
     "finalAnswer": "n = \\frac{t-1}{2}"
    }
