      {
       "title": "Use the area formula",
       "lines": [
        {
         "tex": "\\text{Area} &= \\frac{1}{2} \\times \\text{base} \\times \\text{height}"
        },
        {
         "tex": "&= \\frac{1}{2}(9)(3)"
        },
        {
         "tex": "&= \\frac{27}{2}"
        },
        {
         "tex": "&= 13.5 \\text{ units}^2"
        }
       ]
      }
