     "steps": [
      {
       "title": "Find the inner radius",
       "lines": [
        {
         "text": "The Work Section is 40 cm wide, so the inner radius is 40 cm less than the outer radius."
        },
        {
         "tex": "r_{\\text{inner}} &= 160 - 40"
        },
        {
         "tex": "&= 120"
        }
       ]
      },
      {
       "title": "Subtract the inner sector from the outer sector",
       "lines": [
        {
         "text": "Both sectors have angle $250^\\circ$, so each is $\\dfrac{250}{360}$ of a circle."
        },
        {
         "tex": "A &= \\frac{250}{360}\\left[\\pi(160)^2 - \\pi(120)^2\\right]"
        },
        {
         "tex": "&= \\frac{250}{360}\\left[25\\,600\\pi - 14\\,400\\pi\\right]"
        },
        {
         "tex": "&= \\frac{250}{360} \\times 11\\,200\\pi"
        },
        {
         "tex": "&= \\frac{70\\,000\\pi}{9}"
        }
       ]
      },
      {
       "title": "Round to the nearest cm squared",
       "lines": [
        {
         "tex": "&= 24\\,434.6\\ldots"
        },
        {
         "tex": "&\\approx 24\\,435 \\text{ cm}^2"
        }
       ]
      }
     ],
     "finalAnswer": "24\\,435 \\text{ cm}^2"
